<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\AdPlacement; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\Rule; use Inertia\Inertia;
class AdPlacementController extends Controller { public function index(){return Inertia::render('Admin/Advertising/Placements/Index',['placements'=>AdPlacement::withCount('campaigns')->orderBy('location')->orderBy('name')->get()]);} public function create(){return Inertia::render('Admin/Advertising/Placements/Form',['placement'=>null]);} public function store(Request $r){$d=$this->data($r);$d['uuid']=(string)Str::uuid();$d['is_active']=$r->boolean('is_active');AdPlacement::create($d);return to_route('admin.ad-placements.index')->with('success','Placement created.');} public function edit(AdPlacement $adPlacement){return Inertia::render('Admin/Advertising/Placements/Form',['placement'=>$adPlacement]);} public function update(Request $r,AdPlacement $adPlacement){$d=$this->data($r,$adPlacement);$d['is_active']=$r->boolean('is_active');$adPlacement->update($d);return to_route('admin.ad-placements.index')->with('success','Placement updated.');} public function destroy(AdPlacement $adPlacement){abort_if($adPlacement->campaigns()->exists(),422,'Placements assigned to campaigns cannot be deleted.');$adPlacement->delete();return back()->with('success','Placement deleted.');} private function data(Request $r,?AdPlacement $p=null):array{return $r->validate(['name'=>'required|string|max:255','code'=>['required','string','max:100',Rule::unique('ad_placements','code')->ignore($p)],'location'=>'required|string|max:255','format'=>'required|in:banner,card,hero,native,video','width'=>'nullable|integer|min:1','height'=>'nullable|integer|min:1','max_active_campaigns'=>'required|integer|min:1|max:100','base_price_cents'=>'required|integer|min:0','pricing_model'=>'required|in:flat,cpm,cpc,sponsorship','description'=>'nullable|string|max:2000','is_active'=>'nullable|boolean']);} }
